```javascript
import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, float, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new Group();
  group.name = 'hub-journal-card-1-label';
  group.userData.childTimelines = [];

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const cInk = new THREE.Color(colors.ink);
  const cPaper = new THREE.Color(colors.paper);
  const cAccent = new THREE.Color(colors.accent);
  const cSurface = new THREE.Color(colors.surface);

  // ---- Label backdrop: engineered vertical gradient (surface -> ink) ----
  const W = 1.6, H = 1.0;
  const bgGeo = new PlaneGeometry(W, H, 1, 1);

  const bgMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 1 });
  bgMat.colorNode = mix(vec3(cSurface), vec3(cInk), smoothstep(float(0.0), float(1.0), uv().y));
  const bgMesh = new Mesh(bgGeo, bgMat);
  bgMesh.position.set(0, 0, 0);
  group.add(bgMesh);

  // ---- Brushed-metal grain overlay (async texture; assigned when ready) ----
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (group.userData._dead) { tex.dispose?.(); return; }
      try { tex.colorSpace = THREE.SRGBColorSpace; } catch (_) {}
      const grainGeo = new PlaneGeometry(W, H, 1, 1);
      const grainMat = new MeshBasicNodeMaterial({
        transparent: true,
        opacity: 0.22,
        depthWrite: false,
      });
      // dark metallic sheen tinted toward ink; subtle highlight via uv ramp
      grainMat.colorNode = mix(
        vec3(cInk).mul(float(0.45)),
        vec3(cPaper).mul(float(0.18)),
        smoothstep(float(0.2), float(0.9), uv().y)
      );
      // assign the loaded texture so its repeat carries into the node
      grainMat.map = tex;
      grainMat.needsUpdate = true;
      const grainMesh = new Mesh(grainGeo, grainMat);
      grainMesh.position.set(0, 0, 0.002);
      grainMesh.renderOrder = 1;
      group.add(grainMesh);
      group.userData._grainMesh = grainMesh;
      group.userData._grainMat = grainMat;
      group.userData._grainGeo = grainGeo;
      group.userData._tex = tex;
    });
  }

  // ---- Accent rule (thin line, top-left) ----
  const ruleGeo = new PlaneGeometry(W * 0.5, 0.012, 1, 1);
  const ruleMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.95 });
  ruleMat.colorNode = vec3(cAccent);
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(-W * 0.25, H * 0.34, 0.004);
  group.add(rule);

  // ---- Headline: "Journal 1" ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const childMeshes = [];
  for (const item of items) {
    const str = typeof item === 'string' ? item : item.text;
    const role = typeof item === 'string' ? 'headline' : (item.role ?? 'headline');
    const fontSizePx = item.typography?.fontSize ?? 39;
    // atlas fontSize is in scene-em; 39px atlas scale ~0.28 scene units tuned for hub frame
    const fontSizeScene = fontSizePx / 130;
    const textObj = ctx.fontAtlas.createText(String(str), {
      fontSize: fontSizeScene,
      color: colors.paper,
      align: 'left',
      maxWidthPx: W * 2.4,
      letterSpacingPx: 0.0,
    });
    textObj.position.set(-W * 0.46, -H * 0.12, 0.006);
    group.add(textObj);
    childMeshes.push(textObj);
  }

  // ---- Mono index marker "01" in accent (top-right) ----
  const idx = ctx.fontAtlas.createText('01', {
    fontSize: 0.07,
    color: colors.accent,
    align: 'right',
    letterSpacingPx: 0.05,
  });
  idx.position.set(W * 0.46, H * 0.34, 0.006);
  group.add(idx);
  childMeshes.push(idx);

  // ---- Caption label under headline (mono, paper-dim) ----
  const cap = ctx.fontAtlas.createText('ATELIER JOURNAL', {
    fontSize: 0.045,
    color: new THREE.Color(colors.paper).multiplyScalar(0.55).getHexString(),
    align: 'left',
    letterSpacingPx: 0.08,
  });
  cap.position.set(-W * 0.46, -H * 0.34, 0.006);
  group.add(cap);
  childMeshes.push(cap);

  // ---- Handlers (no spec interactions) ----
  group.userData.handlers = {
    click: null,
    hover: null,
    pointermove: null,
    load: () => {
      const tl = gsap.timeline();
      tl.from(group.position, { y: 0.4, duration: 0.7, ease: 'power3.out' }, 0)
        .from(group.scale, { x: 0.98, y: 0.98, duration: 0.7, ease: 'power3.out' }, 0)
        .to(group.scale, { x: 1.04, y: 1.04, duration: 0.45, ease: 'power2.out' }, 0.4)
        .to(group.scale, { x: 1.0, y: 1.0, duration: 0.45, ease: 'power4.out' }, 0.85);
      group.userData.childTimelines.push(tl);
    },
  };

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    group.userData._dead = true;
    for (const tl of group.userData.childTimelines) { try { tl.kill(); } catch (_) {} }
    group.userData.childTimelines.length = 0;
    bgGeo.dispose(); bgMat.dispose();
    ruleGeo.dispose(); ruleMat.dispose();
    if (group.userData._grainGeo) group.userData._grainGeo.dispose();
    if (group.userData._grainMat) group.userData._grainMat.dispose();
    if (group.userData._tex) group.userData._tex.dispose?.();
    for (const m of childMeshes) {
      if (m.traverse) m.traverse((o) => { o.geometry?.dispose?.(); o.material?.dispose?.(); });
    }
  };

  return group;
}
